contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry that drives c and asserts a general property
    function run(address target, bytes memory data, uint sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0) + (sendAmount)); require(sendAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= sendAmount);

        // read Owner and contract balance before any actions
        address ownerBefore = c.Owner(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;

        // Try withdraw as non-owner (this contract is msg.sender to c). It should revert unless this contract is Owner.
        bool withdrawReverted;
        c.withdraw{value: 0}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        // Try Command as non-owner sending sendAmount wei
        bool commandReverted;
        c.Command{value: sendAmount}(target, data); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            commandReverted = true;
        } else {
            commandReverted = false;
        }

        // Owner must remain the same (there is no function to change Owner), and if this contract is not the owner
        // then both withdraw and Command must have reverted. If this contract is the owner, they may succeed.
        bool amIOwner = (ownerBefore == address(this));

        assert(c.Owner() == ownerBefore && (amIOwner || (withdrawReverted && commandReverted)));
    }

    receive() external payable {}
}

